/// Errors from parsing TOML input.
suberror ParseError {
  InvalidSyntax(String)
  DuplicateKey(String)
} derive(Debug)

///|
/// Internal token representation.
enum Token {
  Key(String)
  Equals
  Str(String)
  Int(Int64)
  Bool(Bool)
  LeftBracket
  RightBracket
  Dot
  Comma
  Newline
  Eof
}
"}

