/// Lexer that tokenizes TOML input.
struct Lexer {
  input : String
  pos : Int
  len : Int
}

///|
fn Lexer::new(input : String) -> Lexer {
  { input, pos: 0, len: input.length() }
}

///|
fn peek_char(self : Lexer) -> Char? {
  if self.pos < self.len {
    Some(self.input[self.pos])
  } else {
    None
  }
}

///|
fn advance(self : Lexer) -> Lexer {
  if self.pos < self.len {
    { ..self, pos: self.pos + 1 }
  } else {
    self
  }
}

///|
fn skip_while(self : Lexer, pred : (Char) -> Bool) -> Lexer {
  loop self {
    cur if cur.pos < cur.len && pred(cur.input[cur.pos]) => {
      continue cur.advance()
    }
    cur => cur
  }
}

///|
fn skip_line(self : Lexer) -> Lexer {
  let mut cur = self
  while cur.pos < cur.len && cur.input[cur.pos] != '\n' {
    cur = cur.advance()
  }
  cur
}

///|
fn read_bare_key(self : Lexer) -> (String, Lexer) {
  let mut s = StringBuilder::new()
  let mut cur = self
  while cur.pos < cur.len {
    let c = cur.input[cur.pos]
    if c == '_' || c == '-' || c.to_int() >= 'a'.to_int() && c.to_int() <= 'z'.to_int() ||
      c.to_int() >= 'A'.to_int() && c.to_int() <= 'Z'.to_int() ||
      c.to_int() >= '0'.to_int() && c.to_int() <= '9'.to_int() {
      s.write_char(c)
      cur = cur.advance()
    } else {
      break
    }
  }
  (s.to_string(), cur)
}

///|
fn read_string(self : Lexer) -> (String, Lexer) raise ParseError {
  // We've already consumed the opening quote
  let mut s = StringBuilder::new()
  let mut cur = self
  while cur.pos < cur.len {
    let c = cur.input[cur.pos]
    if c == '"' {
      cur = cur.advance()
      return (s.to_string(), cur)
    } else if c == '\\' {
      cur = cur.advance()
      if cur.pos >= cur.len {
        raise InvalidSyntax("unterminated string escape")
      }
      let esc = cur.input[cur.pos]
      cur = cur.advance()
      match esc {
        '"' => s.write_char('"')
        '\\' => s.write_char('\\')
        'n' => s.write_char('\n')
        't' => s.write_char('\t')
        _ => raise InvalidSyntax("invalid escape sequence: \\" + Char::from_int(esc.to_int()))
      }
    } else if c == '\n' {
      raise InvalidSyntax("newline in string")
    } else {
      s.write_char(c)
      cur = cur.advance()
    }
  }
  raise InvalidSyntax("unterminated string")
}

///|
fn read_int(self : Lexer) -> (Int64, Lexer) raise ParseError {
  let mut s = StringBuilder::new()
  let mut cur = self
  if cur.pos < cur.len && cur.input[cur.pos] == '-' {
    s.write_char('-')
    cur = cur.advance()
  }
  while cur.pos < cur.len {
    let c = cur.input[cur.pos]
    if c.to_int() >= '0'.to_int() && c.to_int() <= '9'.to_int() {
      s.write_char(c)
      cur = cur.advance()
    } else if c == '_' {
      // Digit separators are allowed in TOML integers
      cur = cur.advance()
    } else {
      break
    }
  }
  let text = s.to_string()
  if text.is_empty() || text == "-" {
    raise InvalidSyntax("invalid integer")
  }
  let n : Int64 = @string.from_str(text) catch {
    _ => raise InvalidSyntax("invalid integer: " + text)
  }
  (n, cur)
}

///|
fn read_bool(self : Lexer) -> (Bool, Lexer) raise ParseError {
  let cur = self
  let remaining = if cur.pos + 4 <= cur.len {
    Some(cur.input.sub(start=cur.pos, end=cur.pos + 4).to_owned())
  } else {
    None
  }
  if remaining == Some("true") {
    (true, { ..cur, pos: cur.pos + 4 })
  } else if cur.pos + 5 <= cur.len &&
    cur.input.sub(start=cur.pos, end=cur.pos + 5).to_owned() == "false" {
    (false, { ..cur, pos: cur.pos + 5 })
  } else {
    raise InvalidSyntax("invalid value")
  }
}

///|
fn next_token(self : Lexer) -> (Token, Lexer) raise ParseError {
  let mut cur = self
  // Skip whitespace and newlines (non-semantic newlines)
  // Actually, newlines are significant in TOML (they separate key-value pairs)
  // But we skip leading whitespace and handle newlines as tokens
  loop {
    if cur.pos >= cur.len {
      break (Eof, cur)
    }
    let c = cur.input[cur.pos]
    if c == ' ' || c == '\t' || c == '\r' {
      cur = cur.advance()
    } else if c == '#' {
      cur = cur.skip_line()
      // After a comment, we might be at a newline or EOF
      if cur.pos < cur.len && cur.input[cur.pos] == '\n' {
        cur = cur.advance()
        break (Newline, cur)
      }
      // Continue skipping whitespace/comments
    } else if c == '\n' {
      cur = cur.advance()
      break (Newline, cur)
    } else if c == '=' {
      cur = cur.advance()
      break (Equals, cur)
    } else if c == '[' {
      cur = cur.advance()
      break (LeftBracket, cur)
    } else if c == ']' {
      cur = cur.advance()
      break (RightBracket, cur)
    } else if c == '.' {
      cur = cur.advance()
      break (Dot, cur)
    } else if c == ',' {
      cur = cur.advance()
      break (Comma, cur)
    } else if c == '"' {
      cur = cur.advance()
      let (val, new_cur) = read_string(cur)
      cur = new_cur
      break (Str(val), cur)
    } else if c == 't' || c == 'f' {
      // Try to read a boolean
      let (val, new_cur) = read_bool(cur)
      cur = new_cur
      break (Bool(val), cur)
    } else if (c.to_int() >= 'a'.to_int() && c.to_int() <= 'z'.to_int()) ||
      (c.to_int() >= 'A'.to_int() && c.to_int() <= 'Z'.to_int()) ||
      c == '_' || c == '-' ||
      (c.to_int() >= '0'.to_int() && c.to_int() <= '9'.to_int()) {
      let (val, new_cur) = read_bare_key(cur)
      cur = new_cur
      // Check if it's an integer
      let is_int = val.length() > 0 &&
        (val[0].to_int() >= '0'.to_int() && val[0].to_int() <= '9'.to_int() ||
          val[0] == '-' && val.length() > 1)
      if is_int {
        let n : Int64 = @string.from_str(val) catch {
          _ => raise InvalidSyntax("invalid integer: " + val)
        }
        break (Int(n), cur)
      }
      break (Key(val), cur)
    } else if c.to_int() >= '0'.to_int() && c.to_int() <= '9'.to_int() {
      // Number starting with digit
      let (val, new_cur) = read_int(cur)
      cur = new_cur
      break (Int(val), cur)
    } else {
      raise InvalidSyntax("unexpected character: " + Char::from_int(c.to_int()))
    }
  }
  (Eof, cur) // unreachable if loop breaks
}
"}

