/// Lexer that tokenizes TOML input.
struct Lexer {
  input : String
  pos : Int
  len : Int
}

///|
fn Lexer::new(input : String) -> Lexer {
  { input, pos: 0, len: input.length() }
}

///|
fn peek_char(self : Lexer) -> Char? {
  if self.pos < self.len {
    Some(self.input[self.pos])
  } else {
    None
  }
}

///|
fn advance(self : Lexer) -> Lexer {
  if self.pos < self.len {
    { ..self, pos: self.pos + 1 }
  } else {
    self
  }
}

///|
fn skip_while(self : Lexer, pred : (Char) -> Bool) -> Lexer {
  loop self {
    cur if cur.pos < cur.len && pred(cur.input[cur.pos]) => {
      continue cur.advance()
    }
    cur => break cur
  }
}

///|
fn skip_line(self : Lexer) -> Lexer {
  let mut cur = self
  while cur.pos < cur.len && cur.input[cur.pos] != '\n' {
    cur = cur.advance()
  }
  cur
}

///|
fn read_bare_key(self : Lexer) -> (String, Lexer) {
  let mut s = StringBuilder::new()
  let mut cur = self
  while cur.pos < cur.len {
    let c = cur.input[cur.pos]
    let code = c.to_int()
    if (code >= 'a'.to_int() && code <= 'z'.to_int()) ||
      (code >= 'A'.to_int() && code <= 'Z'.to_int()) ||
      (code >= '0'.to_int() && code <= '9'.to_int()) || c == '_' || c == '-' {
      s.write_char(c)
      cur = cur.advance()
    } else {
      break
    }
  }
  (s.to_string(), cur)
}

///|
fn read_string(self : Lexer) -> (String, Lexer) raise ParseError {
  let mut s = StringBuilder::new()
  let mut cur = self
  while cur.pos < cur.len {
    let c = cur.input[cur.pos]
    if c == '"' {
      cur = cur.advance()
      return (s.to_string(), cur)
    } else if c == '\\' {
      cur = cur.advance()
      if cur.pos >= cur.len {
        raise InvalidSyntax("unterminated string escape")
      }
      let esc = cur.input[cur.pos]
      cur = cur.advance()
      match esc {
        '"' => s.write_char('"')
        '\\' => s.write_char('\\')
        'n' => s.write_char('\n')
        't' => s.write_char('\t')
        _ => raise InvalidSyntax("invalid escape sequence: \\" + Char::from_int(esc.to_int()))
      }
    } else if c == '\n' {
      raise InvalidSyntax("newline in string")
    } else {
      s.write_char(c)
      cur = cur.advance()
    }
  }
  raise InvalidSyntax("unterminated string")
}

///|
fn read_int(self : Lexer) -> (Int64, Lexer) raise ParseError {
  let mut s = StringBuilder::new()
  let mut cur = self
  if cur.pos < cur.len && cur.input[cur.pos] == '-' {
    s.write_char('-')
    cur = cur.advance()
  }
  while cur.pos < cur.len {
    let c = cur.input[cur.pos]
    let code = c.to_int()
    if code >= '0'.to_int() && code <= '9'.to_int() {
      s.write_char(c)
      cur = cur.advance()
    } else if c == '_' {
      cur = cur.advance()
    } else {
      break
    }
  }
  let text = s.to_string()
  if text.is_empty() || text == "-" {
    raise InvalidSyntax("invalid integer")
  }
  let n : Int64 = @string.from_str(text) catch {
    _ => raise InvalidSyntax("invalid integer: " + text)
  }
  (n, cur)
}

///|
fn read_bool(self : Lexer) -> (Bool, Lexer) raise ParseError {
  if self.pos + 4 <= self.len &&
    self.input.sub(start=self.pos, end=self.pos + 4).to_owned() == "true" {
    (true, { ..self, pos: self.pos + 4 })
  } else if self.pos + 5 <= self.len &&
    self.input.sub(start=self.pos, end=self.pos + 5).to_owned() == "false" {
    (false, { ..self, pos: self.pos + 5 })
  } else {
    raise InvalidSyntax("invalid boolean value")
  }
}

///|
/// Get the next token from the lexer.
fn next_token(self : Lexer) -> (Token, Lexer) raise ParseError {
  loop self {
    cur if cur.pos >= cur.len => break (Eof, cur)
    cur =>
      // Skip whitespace (but not newlines)
      if cur.input[cur.pos] == ' ' || cur.input[cur.pos] == '\t' ||
        cur.input[cur.pos] == '\r' {
        continue cur.advance()
      } else if cur.input[cur.pos] == '#' {
        // Skip comment and the newline after it
        let after_comment = cur.skip_line()
        if after_comment.pos < after_comment.len &&
          after_comment.input[after_comment.pos] == '\n' {
          continue after_comment.advance()
        } else {
          break (Newline, after_comment)
        }
      } else if cur.input[cur.pos] == '\n' {
        break (Newline, cur.advance())
      } else if cur.input[cur.pos] == '=' {
        break (Equals, cur.advance())
      } else if cur.input[cur.pos] == '[' {
        break (LeftBracket, cur.advance())
      } else if cur.input[cur.pos] == ']' {
        break (RightBracket, cur.advance())
      } else if cur.input[cur.pos] == '.' {
        break (Dot, cur.advance())
      } else if cur.input[cur.pos] == ',' {
        break (Comma, cur.advance())
      } else if cur.input[cur.pos] == '"' {
        let after_quote = cur.advance()
        let (val, new_cur) = read_string(after_quote)
        break (Str(val), new_cur)
      } else if cur.input[cur.pos] == 't' || cur.input[cur.pos] == 'f' {
        // Try boolean first
        let (val, new_cur) = read_bool(cur)
        break (Bool(val), new_cur)
      } else if cur.input[cur.pos] == '-' {
        // Could be negative number or bare key starting with dash
        let after_dash = cur.advance()
        if after_dash.pos < after_dash.len &&
          after_dash.input[after_dash.pos].to_int() >= '0'.to_int() &&
          after_dash.input[after_dash.pos].to_int() <= '9'.to_int() {
          let (val, new_cur) = read_int(cur)
          break (Int(val), new_cur)
        } else {
          // Part of a key that starts with dash
          let (val, new_cur) = read_bare_key(cur)
          break (Key(val), new_cur)
        }
      } else {
        let code = cur.input[cur.pos].to_int()
        if (code >= 'a'.to_int() && code <= 'z'.to_int()) ||
          (code >= 'A'.to_int() && code <= 'Z'.to_int()) ||
          code == '_' ||
          (code >= '0'.to_int() && code <= '9'.to_int()) {
          let (val, new_cur) = read_bare_key(cur)
          // Check if it's an integer
          if val.length() > 0 &&
            val[0].to_int() >= '0'.to_int() && val[0].to_int() <= '9'.to_int() {
            let n : Int64 = @string.from_str(val) catch {
              _ => raise InvalidSyntax("invalid integer: " + val)
            }
            break (Int(n), new_cur)
          }
          break (Key(val), new_cur)
        } else {
          raise InvalidSyntax(
            "unexpected character: " + Char::from_int(code).to_string(),
          )
        }
      }
  }
}
"}

{"path": "/private/tmp/prompt_demos/runs_flash-guidelines/workspaces/04/toml_parser.mbt", "content": "///|
/// A helper to build a nested JSON object from a table path and value.
fn set_at_path(
  root : Map[String, Json],
  path : List[String],
  key : String,
  value : Json
) -> Map[String, Json] raise ParseError {
  match path {
    Nil =>
      // Set at top level
      if root.contains(key) {
        raise DuplicateKey("duplicate key: " + key)
      }
      root.insert(key, value)
    Cons(head, tail) =>
      let sub = match root.get(head) {
        Some(Json::Object(m)) => m
        None => Map::new()
        Some(_) => raise DuplicateKey(
          "key conflict: " + head + " is not a table",
        )
      }
      let new_sub = set_at_path(sub, tail, key, value)
      root.insert(head, Json::object(new_sub))
  }
}

///|
/// Ensure a table path exists in the root map, creating nested maps as needed.
fn ensure_table_path(
  root : Map[String, Json],
  path : List[String]
) -> Map[String, Json] raise ParseError {
  match path {
    Nil => root
    Cons(head, tail) =>
      let sub = match root.get(head) {
        Some(Json::Object(m)) => m
        None => Map::new()
        Some(_) => raise DuplicateKey(
          "key conflict: cannot redefine " + head + " as table",
        )
      }
      let new_sub = ensure_table_path(sub, tail)
      root.insert(head, Json::object(new_sub))
  }
}

///|
/// Parse a list of dotted key segments: read key segments separated by dots.
fn parse_key_tokens(self : Lexer) -> (List[String], Lexer) raise ParseError {
  let (first_key, cur) = self |> read_key_atom
  let mut keys = List::new()
  keys = Cons(first_key, keys)
  let mut cur_pos = cur
  // Look for more dots and keys
  loop cur_pos {
    cur2 =>
      let (tok, next) = next_token(cur2)
      match tok {
        Dot =>
          let (next_key, after_key) = read_key_atom(next)
          keys = Cons(next_key, keys)
          continue after_key
        _ =>
          // No more dotted keys, put back the token
          break (List::reverse(keys), cur2)
      }
  }
}

///|
fn read_key_atom(self : Lexer) -> (String, Lexer) raise ParseError {
  let (tok, cur) = next_token(self)
  match tok {
    Key(k) => (k, cur)
    Str(k) => (k, cur)
    _ => raise InvalidSyntax("expected a key, got " + token_preview(tok))
  }
}

///|
fn token_preview(tok : Token) -> String {
  match tok {
    Key(k) => "key \"" + k + "\""
    Equals => "'='"
    Str(s) => "string \"" + s + "\""
    Int(n) => "integer " + n.to_string()
    Bool(b) => "boolean " + b.to_string()
    LeftBracket => "'['"
    RightBracket => "']'"
    Dot => "'.'"
    Comma => "','"
    Newline => "newline"
    Eof => "end of input"
  }
}

///|
/// Parse a value (string, integer, boolean, or array).
fn parse_value(self : Lexer) -> (Json, Lexer) raise ParseError {
  let (tok, cur) = next_token(self)
  match tok {
    Str(s) => (Json::string(s), cur)
    Int(n) => (Json::number(n.to_double()), cur)
    Bool(b) => (Json::boolean(b), cur)
    LeftBracket => parse_array(cur)
    _ => raise InvalidSyntax("expected a value, got " + token_preview(tok))
  }
}

///|
/// Parse a TOML array literal: [ val1, val2, ... ]
fn parse_array(self : Lexer) -> (Json, Lexer) raise ParseError {
  let mut items : Array[Json] = []
  let mut cur = self
  // Skip optional whitespace/newlines after [
  loop {
    let (tok, next) = next_token(cur)
    match tok {
      RightBracket => break (Json::array(items), next)
      Comma | Newline =>
        // Skip separators
        cur = next
        continue
      _ =>
        // It's a value
        let (val, after_val) = parse_value_from_token(tok, next)
        items.push(val)
        cur = after_val
        continue
    }
  }
}

///|
fn parse_value_from_token(tok : Token, lexer : Lexer) -> (Json, Lexer) raise ParseError {
  match tok {
    Str(s) => (Json::string(s), lexer)
    Int(n) => (Json::number(n.to_double()), lexer)
    Bool(b) => (Json::boolean(b), lexer)
    LeftBracket => parse_array(lexer)
    _ => raise InvalidSyntax("expected a value, got " + token_preview(tok))
  }
}

///|
/// Parse a complete TOML document.
fn parse_toml(input : String) -> Json raise ParseError {
  let lexer = Lexer::new(input)
  let mut root : Map[String, Json] = Map::new()
  let mut current_path : List[String] = Nil
  let mut cur = lexer

  loop cur {
    lex =>
      let (tok, next) = next_token(lex)
      match tok {
        Eof => break Json::object(root)
        Newline =>
          // Skip blank lines
          continue next
        LeftBracket =>
          // Table header: [path]
          let (path_tok, after_bracket) = next_token(next)
          let (table_keys, after_keys) = match path_tok {
            LeftBracket =>
              // This would be [[array of tables]], not supported in our subset
              raise InvalidSyntax("array of tables not supported")
            _ =>
              // Parse key list
              let start_lex = next  // re-parse from after [
              let (keys, k_cur) = parse_key_tokens(start_lex)
              // Expect ]
              let (close_tok, after_close) = next_token(k_cur)
              match close_tok {
                RightBracket => (keys, after_close)
                _ => raise InvalidSyntax(
                  "expected ']' after table key, got " + token_preview(close_tok),
                )
              }
          }
          current_path = table_keys
          root = ensure_table_path(root, current_path)
          // After a table header, expect newline or EOF
          let (after_tok, after_newline) = next_token(after_keys)
          match after_tok {
            Newline | Eof => continue after_newline
            _ => raise InvalidSyntax(
              "expected newline after table header, got " + token_preview(after_tok),
            )
          }
        _ =>
          // It's a key-value pair
          // Put back the token and parse key
          let (keys, key_cur) = {
            // The token we already got could be a key or a value-type token
            // If it starts a key-value, it should be a Key or Str token
            match tok {
              Key(k) | Str(k) =>
                // Check if it's followed by = or .
                let (next_tok, after_key) = next_token(next)
                match next_tok {
                  Dot =>
                    // Dotted key
                    let key_lex = next  // re-read from after first token
                    parse_key_tokens(key_lex)
                  Equals =>
                    // Simple key = value
                    (Cons(k, Nil), after_key)
                  _ => raise InvalidSyntax(
                    "expected '=' after key, got " + token_preview(next_tok),
                  )
                }
              _ => raise InvalidSyntax(
                "expected a key-value pair, got " + token_preview(tok),
              )
            }
          }

          // Expect =
          let (eq_tok, after_eq) = next_token(key_cur)
          match eq_tok {
            Equals => {
              // Parse value
              let (value, after_value) = parse_value(after_eq)
              // Handle the key
              match keys {
                Cons(k, rest) =>
                  root = set_at_path(root, current_path, k, value)
                  // If there are more key segments, we need to build nested maps
                  fn go(map, remaining_keys : List[String], final_key : String, val) {
                    match remaining_keys {
                      Nil => map  // already set
                      Cons(h, t) => map  // shouldn't happen
                    }
                  }
                  let _ = go  // placeholder for future dotted assignment
                  ()
                Nil => ()
              }

              // Actually, for dotted keys like a.b.c = value, we need to create
              // nested objects: {"a": {"b": {"c": value}}}
              // Re-implement properly:
              fn assign_dotted(m : Map[String, Json], ks : List[String], v : Json) -> Map[
                  String,
                  Json,
                ] raise ParseError {
                match ks {
                  Cons(k, Nil) =>
                    if m.contains(k) { raise DuplicateKey("duplicate key: " + k) }
                    m.insert(k, v)
                  Cons(k, rest) =>
                    let sub = match m.get(k) {
                      Some(Json::Object(sm)) => sm
                      None => Map::new()
                      Some(_) => raise DuplicateKey(
                        "key conflict: " + k + " is not a table",
                      )
                    }
                    let new_sub = assign_dotted(sub, rest, v)
                    m.insert(k, Json::object(new_sub))
                  Nil => m
                }
              }
              root = assign_dotted(root, keys, value)

              // Expect newline or EOF
              let (after_tok, after_line) = next_token(after_value)
