fn mk_obj(m : Map[String, Json]) -> Json { Json::object(m) }

///|
/// Set a value at a path in a nested map structure.
/// The path is the table path (list of parent table names).
/// The key is the final key within the last table.
fn map_set(
  m : Map[String, Json],
  path : List[String],
  key : String,
  value : Json
) -> Map[String, Json] raise ParseError {
  match path {
    Nil =>
      if m.contains(key) {
        raise DuplicateKey("duplicate key: " + key)
      }
      m.insert(key, value)
    Cons(head, tail) =>
      let sub = match m.get(head) {
        Some(Json::Object(sm)) => sm
        None => Map::new()
        Some(_) => raise DuplicateKey(
          "key conflict: " + head + " is not a table",
        )
      }
      let new_sub = map_set(sub, tail, key, value)
      m.insert(head, mk_obj(new_sub))
  }
}

///|
/// Ensure a table path exists, creating nested empty maps.
fn ensure_path(
  m : Map[String, Json],
  path : List[String]
) -> Map[String, Json] raise ParseError {
  match path {
    Nil => m
    Cons(head, tail) =>
      let sub = match m.get(head) {
        Some(Json::Object(sm)) => sm
        None => Map::new()
        Some(_) => raise DuplicateKey(
          "key conflict: cannot redefine " + head + " as table",
        )
      }
      let new_sub = ensure_path(sub, tail)
      m.insert(head, mk_obj(new_sub))
  }
}

///|
/// Set a dotted key (a.b.c = value) in a map.
fn set_dotted_key(
  m : Map[String, Json],
  keys : List[String],
  value : Json
) -> Map[String, Json] raise ParseError {
  match keys {
    Cons(k, Nil) =>
      if m.contains(k) {
        raise DuplicateKey("duplicate key: " + k)
      }
      m.insert(k, value)
    Cons(k, rest) =>
      let sub = match m.get(k) {
        Some(Json::Object(sm)) => sm
        None => Map::new()
        Some(_) => raise DuplicateKey(
          "key conflict: " + k + " is not a table",
        )
      }
      let new_sub = set_dotted_key(sub, rest, value)
      m.insert(k, mk_obj(new_sub))
    Nil => m
  }
}

///|
/// Read a key segment (bare key or quoted string).
fn read_key_segment(self : Lexer) -> (String, Lexer) raise ParseError {
  let (tok, cur) = next_token(self)
  match tok {
    Key(k) => (k, cur)
    Str(k) => (k, cur)
    _ => raise InvalidSyntax("expected a key, got " + tok.to_string())
  }
}

///|
/// Parse a dotted key list.
fn read_key_list(self : Lexer) -> (List[String], Lexer) raise ParseError {
  let (first, cur) = read_key_segment(self)
  let mut keys : List[String] = Cons(first, Nil)
  let mut cur_lex = cur
  loop {
    let (tok, next) = next_token(cur_lex)
    match tok {
      Dot =>
        let (seg, after) = read_key_segment(next)
        keys = Cons(seg, keys)
        cur_lex = after
        continue
      _ =>
        // Not a dotted key; put back the token
        // We can't put back, so we pass the token info
        break (List::reverse(keys), cur_lex)
    }
  }
}

///|
/// Parse a value and return Json + next lexer.
fn read_value(self : Lexer) -> (Json, Lexer) raise ParseError {
  let (tok, cur) = next_token(self)
  read_value_from_tok(tok, cur)
