///|
fn read_value_from_tok(tok : Token, lexer : Lexer) -> (Json, Lexer) raise ParseError {
  match tok {
    Str(s) => (Json::string(s), lexer)
    Int(n) => (Json::number(n.to_double()), lexer)
    Bool(b) => (Json::boolean(b), lexer)
    LeftBracket => read_array(lexer)
    _ => raise InvalidSyntax("expected a value, got " + tok.to_string())
  }
}

///|
/// Parse a TOML array [val1, val2, ...]
fn read_array(self : Lexer) -> (Json, Lexer) raise ParseError {
  let mut items : Array[Json] = []
  let mut after_items = self
  // Skip initial whitespace/newlines
  loop {
    let (tok, next) = next_token(after_items)
    match tok {
      RightBracket => break (Json::array(items), next)
      Comma | Newline =>
