/// Tokenize a full TOML document into an array of tokens.
pub fn tokenize(input : String) -> Array[Token] raise ParseError {
  let len = input.length()
  let mut pos = 0
  let mut tokens : Array[Token] = []

  while pos < len {
    let c = input[pos]
    // Skip whitespace (not newlines)
    if c == ' ' || c == '\t' || c == '\r' {
      pos = pos + 1
    } else if c == '#' {
      // Skip comment
      while pos < len && input[pos] != '\n' { pos = pos + 1 }
    } else if c == '\n' {
      tokens.push(Newline)
      pos = pos + 1
    } else if c == '=' {
      tokens.push(Equals)
      pos = pos + 1
    } else if c == '[' {
      tokens.push(LeftBracket)
      pos = pos + 1
    } else if c == ']' {
      tokens.push(RightBracket)
      pos = pos + 1
    } else if c == '.' {
      tokens.push(Dot)
      pos = pos + 1
    } else if c == ',' {
      tokens.push(Comma)
      pos = pos + 1
    } else if c == '"' {
      let (s, new_pos) = read_string(input, pos + 1)
      tokens.push(Str(s))
      pos = new_pos
    } else if c == 't' || c == 'f' {
      if pos + 4 <= len && input.sub(start=pos, end=pos + 4).to_owned() == "true" {
        tokens.push(Bool(true))
        pos = pos + 4
      } else if pos + 5 <= len &&
        input.sub(start=pos, end=pos + 5).to_owned() == "false" {
        tokens.push(Bool(false))
        pos = pos + 5
      } else {
        // Not a boolean, could be a bare key
        let (s, new_pos) = read_bare_key(input, pos)
        tokens.push(Key(s))
        pos = new_pos
      }
    } else if c == '-' {
      // Could be negative number, or part of a key
      if pos + 1 < len && input[pos + 1].to_int() >= '0'.to_int() &&
        input[pos + 1].to_int() <= '9'.to_int() {
        let (n, new_pos) = read_int(input, pos)
        tokens.push(Int(n))
        pos = new_pos
      } else {
        let (s, new_pos) = read_bare_key(input, pos)
        tokens.push(Key(s))
        pos = new_pos
      }
    } else {
      let code = c.to_int()
      if (code >= 'a'.to_int() && code <= 'z'.to_int()) ||
        (code >= 'A'.to_int() && code <= 'Z'.to_int()) ||
        code == '_' ||
        (code >= '0'.to_int() && code <= '9'.to_int()) {
        let (s, new_pos) = read_bare_key(input, pos)
        // Check if it's an integer
        if s.length() > 0 && s[0].to_int() >= '0'.to_int() &&
          s[0].to_int() <= '9'.to_int() {
          let n : Int64 = @string.from_str(s) catch {
            _ => raise InvalidSyntax("invalid integer: " + s)
          }
          tokens.push(Int(n))
        } else {
          tokens.push(Key(s))
        }
        pos = new_pos
      } else {
        raise InvalidSyntax("unexpected character: " + Char::from_int(code).to_string())
      }
    }
  }
  tokens.push(Eof)
  tokens
}

///|
fn read_string(input : String, start_pos : Int) -> (String, Int) raise ParseError {
  let mut s = StringBuilder::new()
  let mut pos = start_pos
  let len = input.length()
  while pos < len {
    let c = input[pos]
    if c == '"' {
      pos = pos + 1
      return (s.to_string(), pos)
    } else if c == '\\' {
      if pos + 1 >= len {
        raise InvalidSyntax("unterminated string escape")
      }
      let esc = input[pos + 1]
      pos = pos + 2
      match esc {
        '"' => s.write_char('"')
        '\\' => s.write_char('\\')
        'n' => s.write_char('\n')
        't' => s.write_char('\t')
        _ => raise InvalidSyntax("invalid escape sequence: \\" + Char::from_int(esc.to_int()))
      }
    } else if c == '\n' {
      raise InvalidSyntax("newline in string")
    } else {
      s.write_char(c)
      pos = pos + 1
    }
  }
  raise InvalidSyntax("unterminated string")
}

///|
fn read_bare_key(input : String, start_pos : Int) -> (String, Int) {
  let mut s = StringBuilder::new()
  let mut pos = start_pos
  let len = input.length()
  while pos < len {
    let c = input[pos]
    let code = c.to_int()
    if (code >= 'a'.to_int() && code <= 'z'.to_int()) ||
      (code >= 'A'.to_int() && code <= 'Z'.to_int()) ||
      (code >= '0'.to_int() && code <= '9'.to_int()) ||
      c == '_' || c == '-' {
      s.write_char(c)
      pos = pos + 1
    } else {
      break
    }
  }
  (s.to_string(), pos)
}

///|
fn read_int(input : String, start_pos : Int) -> (Int64, Int) raise ParseError {
  let mut s = StringBuilder::new()
  let mut pos = start_pos
  let len = input.length()
  if pos < len && input[pos] == '-' {
    s.write_char('-')
    pos = pos + 1
  }
  while pos < len {
    let c = input[pos]
    let code = c.to_int()
    if code >= '0'.to_int() && code <= '9'.to_int() {
      s.write_char(c)
      pos = pos + 1
    } else if c == '_' {
      // Digit separator
      pos = pos + 1
    } else {
      break
    }
  }
  let text = s.to_string()
  if text.is_empty() || text == "-" {
    raise InvalidSyntax("invalid integer")
  }
  let n : Int64 = @string.from_str(text) catch {
    _ => raise InvalidSyntax("invalid integer: " + text)
  }
  (n, pos)
}
"}

