/// Parser that works on a token array.
struct Parser {
  tokens : Array[Token]
  pos : Int
}

///|
fn Parser::new(tokens : Array[Token]) -> Parser {
  { tokens, pos: 0 }
}

///|
fn peek(self : Parser) -> Token {
  if self.pos < self.tokens.length() {
    self.tokens[self.pos]
  } else {
    Eof
  }
}

///|
fn advance(self : Parser) -> Parser {
  { ..self, pos: self.pos + 1 }
}

///|
fn expect(self : Parser, expected : Token) -> Parser raise ParseError {
  let tok = self.peek()
  if tok != expected {
    raise InvalidSyntax(
      "expected " + expected.to_string() + ", got " + tok.to_string(),
    )
  }
  self.advance()
}

///|
/// Consume newline tokens.
fn skip_newlines(self : Parser) -> Parser {
  let mut p = self
  while p.peek() == Newline {
    p = p.advance()
  }
  p
}

///|
/// Read a key atom (bare key or quoted string).
fn read_key_atom(self : Parser) -> (String, Parser) raise ParseError {
  match self.peek() {
    Key(k) => (k, self.advance())
    Str(k) => (k, self.advance())
    tok => raise InvalidSyntax("expected a key, got " + tok.to_string())
  }
}

///|
/// Read a dotted key list (a.b.c) and stop at the first non-dot token.
fn read_key_list(self : Parser) -> (List[String], Parser) raise ParseError {
  let (first, p1) = read_key_atom(self)
  let mut keys : List[String] = Cons(first, Nil)
  let mut cur = p1
  loop {
    if cur.peek() != Dot {
      break (List::reverse(keys), cur)
    }
    cur = cur.advance() // consume dot
    let (seg, p2) = read_key_atom(cur)
    keys = Cons(seg, keys)
    cur = p2
  }
}

///|
/// Read a value token (string, int, bool, or array).
fn read_value(self : Parser) -> (Json, Parser) raise ParseError {
  match self.peek() {
    Str(s) => (Json::string(s), self.advance())
    Int(n) => (Json::number(n.to_double()), self.advance())
    Bool(b) => (Json::boolean(b), self.advance())
    LeftBracket => read_array(self.advance())
    tok => raise InvalidSyntax("expected a value, got " + tok.to_string())
  }
}

///|
/// Read a TOML array: [val1, val2, ...]
fn read_array(self : Parser) -> (Json, Parser) raise ParseError {
  let mut items : Array[Json] = []
  let mut cur = self
  loop {
    cur = cur.skip_newlines()
    match cur.peek() {
      RightBracket => break (Json::array(items), cur.advance())
      Comma =>
        cur = cur.advance()
        continue
      _ =>
        let (val, p2) = read_value(cur)
        items.push(val)
        cur = p2
        continue
    }
  }
}

///|
/// Set a dotted key (a.b.c = value) in a map, creating nested objects.
fn set_dotted_key(
  m : Map[String, Json],
  keys : List[String],
  value : Json
) -> Map[String, Json] raise ParseError {
  match keys {
    Cons(k, Nil) =>
      if m.contains(k) {
        raise DuplicateKey("duplicate key: " + k)
      }
      m.insert(k, value)
    Cons(k, rest) =>
      let sub = match m.get(k) {
        Some(Json::Object(sm)) => sm
        None => Map::new()
        Some(_) => raise DuplicateKey(
          "key conflict: " + k + " is not a table",
        )
      }
      let new_sub = set_dotted_key(sub, rest, value)
      m.insert(k, Json::object(new_sub))
    Nil => m
  }
}

///|
/// Ensure a table path exists.
fn ensure_table_path(
  m : Map[String, Json],
  path : List[String]
) -> Map[String, Json] raise ParseError {
  match path {
    Nil => m
    Cons(head, tail) =>
      let sub = match m.get(head) {
        Some(Json::Object(sm)) => sm
        None => Map::new()
        Some(_) => raise DuplicateKey(
          "key conflict: cannot redefine " + head + " as table",
        )
      }
      let new_sub = ensure_table_path(sub, tail)
      m.insert(head, Json::object(new_sub))
  }
}

///|
/// Parse a complete TOML document.
fn parse_toml(input : String) -> Json raise ParseError {
  let tokens = tokenize(input)
  let parser = Parser::new(tokens)
  let mut root : Map[String, Json] = Map::new()
  let mut cur = parser

  loop {
    cur = cur.skip_newlines()
    match cur.peek() {
      Eof => break Json::object(root)
      LeftBracket =>
        // Table header
        let p1 = cur.advance()
        let (path, p2) = read_table_path(p1)
        let p3 = p2.expect(RightBracket)
        root = ensure_table_path(root, path)
        cur = p3.skip_newlines()
        // After table header, expect newline or EOF
        match cur.peek() {
          Newline | Eof => cur = cur.skip_newlines()
          tok => raise InvalidSyntax(
            "expected newline after table header, got " + tok.to_string(),
          )
        }
      _ =>
        // Key-value pair
        let (keys, p1) = read_key_list(cur)
        let p2 = p1.expect(Equals)
        let (value, p3) = read_value(p2)
        root = set_dotted_key(root, keys, value)
        cur = p3.skip_newlines()
        match cur.peek() {
          Newline | Eof => cur = cur.skip_newlines()
          tok => raise InvalidSyntax(
            "expected newline after value, got " + tok.to_string(),
          )
        }
    }
  }
}

///|
/// Read the key path for a table header: [a.b.c] returns [a, b, c].
fn read_table_path(self : Parser) -> (List[String], Parser) raise ParseError {
  let (first, p1) = read_key_atom(self)
  let mut keys = Cons(first, Nil)
  let mut cur = p1
  loop {
    match cur.peek() {
      Dot =>
        cur = cur.advance()
        let (seg, p2) = read_key_atom(cur)
        keys = Cons(seg, keys)
        cur = p2
        continue
      _ => break (List::reverse(keys), cur)
    }
  }
}

///|
/// Public API: parse TOML text into deterministic JSON.
pub fn parse(toml_text : String) -> Json raise ParseError {
  parse_toml(toml_text)
}
"}

