fn read_value(self : Parser) -> (Json, Parser) raise ParseError {
  match self.peek() {
    Str(s) => (Json::string(s), self.advance())
    Int(n) => (Json::number(n.to_double()), self.advance())
    Bool(b) => (Json::boolean(b), self.advance())
    LeftBracket => {
      let (v, p) = read_array(self.advance())
      (v, p)
    }
    tok => raise InvalidSyntax("expected a value, got " + tok.to_string())
  }
}

///|
/// Read a TOML array: [val1, val2, ...]
fn read_array(self : Parser) -> (Json, Parser) raise ParseError {
  let mut items : Array[Json] = []
  let mut cur = self
  loop {
    cur = cur.skip_newlines()
    match cur.peek() {
      RightBracket => break (Json::array(items), cur.advance())
      Comma => {
        cur = cur.advance()
        continue
      }
      _ => {
        let (val, p2) = read_value(cur)
        items.push(val)
        cur = p2
        continue
      }
    }
  }
}

///|
/// Set a dotted or table-key path in a map, creating nested objects.
fn set_nested_key(
  m : Map[String, Json],
  keys : Array[String],
  value : Json,
  idx : Int
) -> Map[String, Json] raise ParseError {
  if idx >= keys.length() {
    m
  } else if idx + 1 == keys.length() {
    let k = keys[idx]
    if m.contains(k) {
      raise DuplicateKey("duplicate key: " + k)
    }
    m.insert(k, value)
  } else {
    let k = keys[idx]
    let sub = match m.get(k) {
      Some(Json::Object(sm)) => sm
      None => Map::new()
      Some(_) => raise DuplicateKey(
        "key conflict: " + k + " is not a table",
      )
    }
    let new_sub = set_nested_key(sub, keys, value, idx + 1)
    m.insert(k, Json::object(new_sub))
  }
}

///|
/// Ensure a table path exists in the map.
fn ensure_path(
  m : Map[String, Json],
  path : Array[String],
  idx : Int
) -> Map[String, Json] raise ParseError {
  if idx >= path.length() {
    m
  } else {
    let k = path[idx]
    let sub = match m.get(k) {
      Some(Json::Object(sm)) => sm
      None => Map::new()
      Some(_) => raise DuplicateKey(
        "key conflict: cannot redefine " + k + " as table",
      )
    }
    let new_sub = ensure_path(sub, path, idx + 1)
    m.insert(k, Json::object(new_sub))
  }
}

///|
/// Parse a complete TOML document into a Json value.
fn parse_toml(input : String) -> Json raise ParseError {
  let tokens = tokenize(input)
  let mut cur = Parser::new(tokens)
  let mut root : Map[String, Json] = Map::new()

  loop {
    cur = cur.skip_newlines()
    match cur.peek() {
      Eof => break Json::object(root)
      LeftBracket => {
        // Table header: [path]
        let p1 = cur.advance()
        let (path, p2) = read_table_path(p1)
        // Expect ]
        match p2.peek() {
          RightBracket => cur = p2.advance()
          tok => raise InvalidSyntax(
            "expected ']' after table key, got " + tok.to_string(),
          )
        }
        root = ensure_path(root, path, 0)
        continue
      }
      _ => {
        // Key-value pair
        let (keys, p1) = read_key_list(cur)
        // Expect =
        match p1.peek() {
          Equals => cur = p1.advance()
          tok => raise InvalidSyntax(
            "expected '=', got " + tok.to_string(),
          )
        }
        let (value, p3) = read_value(cur)
        root = set_nested_key(root, keys, value, 0)
        cur = p3
        continue
      }
    }
  }
}

///|
/// Public API: parse TOML text into deterministic JSON.
pub fn parse(toml_text : String) -> Json raise ParseError {
  parse_toml(toml_text)
}
