///|
fn tokenize_impl(
  input : String,
  len : Int,
  pos : Int,
  tokens : Array[Token]
) -> Array[Token] raise ParseError {
  let mut cur = pos
  while cur < len {
    let code = input[cur].to_int()
    // Skip whitespace (not newlines)
    if code == ' '.to_int() || code == '\t'.to_int() || code == '\r'.to_int() {
      cur = cur + 1
    } else if code == '#'.to_int() {
      // Skip comment to end of line
      while cur < len && input[cur].to_int() != '\n'.to_int() { cur = cur + 1 }
    } else if code == '\n'.to_int() {
      tokens.push(Newline)
      cur = cur + 1
    } else if code == '='.to_int() {
      tokens.push(Equals)
      cur = cur + 1
    } else if code == '['.to_int() {
      tokens.push(LeftBracket)
      cur = cur + 1
    } else if code == ']'.to_int() {
      tokens.push(RightBracket)
      cur = cur + 1
    } else if code == '.'.to_int() {
      tokens.push(Dot)
      cur = cur + 1
    } else if code == ','.to_int() {
      tokens.push(Comma)
      cur = cur + 1
    } else if code == '"'.to_int() {
      let (s, new_pos) = read_string(input, cur + 1)
      tokens.push(Str(s))
      cur = new_pos
    } else if code == 't'.to_int() || code == 'f'.to_int() {
      if cur + 4 <= len &&
        input.sub(start=cur, end=cur + 4).to_owned() == "true" {
        tokens.push(Bool(true))
        cur = cur + 4
      } else if cur + 5 <= len &&
        input.sub(start=cur, end=cur + 5).to_owned() == "false" {
        tokens.push(Bool(false))
        cur = cur + 5
      } else {
        let (s, new_pos) = read_bare_key(input, cur)
        tokens.push(Key(s))
        cur = new_pos
      }
    } else if code == '-'.to_int() {
      // Negative number or part of a bare key
      if cur + 1 < len {
        let next_code = input[cur + 1].to_int()
        if next_code >= '0'.to_int() && next_code <= '9'.to_int() {
          let (n, new_pos) = read_int(input, cur)
          tokens.push(Int(n))
          cur = new_pos
        } else {
          let (s, new_pos) = read_bare_key(input, cur)
          tokens.push(Key(s))
          cur = new_pos
        }
      }
    } else if (code >= 'a'.to_int() && code <= 'z'.to_int()) ||
      (code >= 'A'.to_int() && code <= 'Z'.to_int()) ||
      code == '_'.to_int() ||
      (code >= '0'.to_int() && code <= '9'.to_int()) {
      let (s, new_pos) = read_bare_key(input, cur)
      // Check if it's an integer
      if s.length() > 0 &&
        s[0].to_int() >= '0'.to_int() &&
        s[0].to_int() <= '9'.to_int() {
        let n : Int64 = @string.from_str(s) catch {
          _ => raise InvalidSyntax("invalid integer: " + s)
        }
        tokens.push(Int(n))
      } else {
        tokens.push(Key(s))
      }
      cur = new_pos
    } else {
      raise InvalidSyntax(
        "unexpected character: " + Char::from_int(code).to_string(),
      )
    }
  }
  tokens.push(Eof)
  tokens
}

///|
fn read_string(input : String, start_pos : Int) -> (String, Int) raise ParseError {
  let mut s = StringBuilder::new()
  let mut pos = start_pos
  let len = input.length()
  while pos < len {
    let code = input[pos].to_int()
    if code == '"'.to_int() {
      pos = pos + 1
      return (s.to_string(), pos)
    } else if code == '\\'.to_int() {
      if pos + 1 >= len {
        raise InvalidSyntax("unterminated string escape")
      }
      let esc_code = input[pos + 1].to_int()
      pos = pos + 2
      match Char::from_int(esc_code) {
        c if c == '"' => s.write_char('"')
        c if c == '\\' => s.write_char('\\')
        c if c == 'n' => s.write_char('\n')
        c if c == 't' => s.write_char('\t')
        _ => raise InvalidSyntax(
          "invalid escape sequence",
        )
      }
    } else if code == '\n'.to_int() {
      raise InvalidSyntax("newline in string")
    } else {
      s.write_char(input[pos].unsafe_to_char())
      pos = pos + 1
    }
  }
  raise InvalidSyntax("unterminated string")
}

///|
fn read_bare_key(input : String, start_pos : Int) -> (String, Int) {
  let mut s = StringBuilder::new()
  let mut pos = start_pos
  let len = input.length()
  while pos < len {
    let code = input[pos].to_int()
    if (code >= 'a'.to_int() && code <= 'z'.to_int()) ||
      (code >= 'A'.to_int() && code <= 'Z'.to_int()) ||
      (code >= '0'.to_int() && code <= '9'.to_int()) ||
      code == '_'.to_int() || code == '-'.to_int() {
      s.write_char(input[pos].unsafe_to_char())
      pos = pos + 1
    } else {
      break
    }
  }
  (s.to_string(), pos)
}

///|
fn read_int(input : String, start_pos : Int) -> (Int64, Int) raise ParseError {
  let mut s = StringBuilder::new()
  let mut pos = start_pos
  let len = input.length()
  if pos < len && input[pos].to_int() == '-'.to_int() {
    s.write_char('-')
    pos = pos + 1
  }
  while pos < len {
    let code = input[pos].to_int()
    if code >= '0'.to_int() && code <= '9'.to_int() {
      s.write_char(input[pos].unsafe_to_char())
      pos = pos + 1
    } else if code == '_'.to_int() {
      pos = pos + 1
    } else {
      break
    }
  }
  let text = s.to_string()
  if text.is_empty() || text == "-" {
    raise InvalidSyntax("invalid integer")
  }
  let n : Int64 = @string.from_str(text) catch {
    _ => raise InvalidSyntax("invalid integer: " + text)
  }
  (n, pos)
}
