struct Parser {
  tokens : Array[Token]
  pos : Int
}

///|
fn Parser::new(tokens : Array[Token]) -> Parser {
  { tokens, pos: 0 }
}

///|
fn peek(self : Parser) -> Token {
  if self.pos < self.tokens.length() {
    self.tokens[self.pos]
  } else {
    Eof
  }
}

///|
fn advance(self : Parser) -> Parser {
  { ..self, pos: self.pos + 1 }
}

///|
/// Skip newline tokens.
fn skip_newlines(self : Parser) -> Parser {
  let mut p = self
  while (match p.peek() { Newline => true; _ => false }) {
    p = p.advance()
  }
  p
}

///|
/// Read a key atom (bare key or quoted string).
fn read_key_atom(self : Parser) -> (String, Parser) raise ParseError {
  match self.peek() {
    Key(k) => (k, self.advance())
    Str(k) => (k, self.advance())
    tok => raise InvalidSyntax("expected a key, got " + tok.to_string())
  }
}

///|
/// Read a dotted key list into an array, stopping at first non-dot/key token.
fn read_key_list(self : Parser) -> (Array[String], Parser) raise ParseError {
  let (first, p1) = read_key_atom(self)
  let mut keys : Array[String] = [first]
  let mut cur = p1
  while true {
    match cur.peek() {
      Dot => {
        cur = cur.advance()
        let (seg, p2) = read_key_atom(cur)
        keys.push(seg)
        cur = p2
        continue
      }
      _ => break (keys, cur)
    }
  }
}

///|
/// Read the key path for a table header: [a.b.c] -> array [a, b, c].
fn read_table_path(self : Parser) -> (Array[String], Parser) raise ParseError {
  let (first, p1) = read_key_atom(self)
  let mut keys : Array[String] = [first]
  let mut cur = p1
  while true {
    match cur.peek() {
      Dot => {
        cur = cur.advance()
        let (seg, p2) = read_key_atom(cur)
        keys.push(seg)
        cur = p2
        continue
      }
      _ => break (keys, cur)
    }
  }
}

///|
/// Read a value (string, int, bool, or start of array).
fn read_value(self : Parser) -> (Json, Parser) raise ParseError {
  match self.peek() {
    Str(s) => (Json::string(s), self.advance())
    Int(n) => (Json::number(n.to_double()), self.advance())
    Bool(b) => (Json::boolean(b), self.advance())
    LeftBracket => {
      let (v, p) = read_array(self.advance())
      (v, p)
    }
    tok => raise InvalidSyntax("expected a value, got " + tok.to_string())
  }
}

///|
/// Read a TOML array: [val1, val2, ...]
fn read_array(self : Parser) -> (Json, Parser) raise ParseError {
  let mut items : Array[Json] = []
  let mut cur = self
  while true {
    cur = cur.skip_newlines()
    match cur.peek() {
      RightBracket => break (Json::array(items), cur.advance())
      Comma => {
        cur = cur.advance()
        continue
      }
      _ => {
        let (val, p2) = read_value(cur)
        items.push(val)
        cur = p2
        continue
      }
    }
  }
