    m[k] = value
    m
  } else {
    let k = keys[idx]
    let sub = match m.get(k) {
      Some(Json::Object(sm)) => sm
      None => Map::new()
      Some(_) => raise DuplicateKey(
        "key conflict: " + k + " is not a table",
      )
    }
    let new_sub = set_nested_key(sub, keys, value, idx + 1)
    m[k] = Json::object(new_sub)
    m
  }
