struct Config {
  path : String
  stdin : Bool
}

///|
fn config_from_matches(matches : @argparse.Matches) -> Config raise {
  // matches.flags is a Map or similar structure
  let stdin = match matches.value_by_flag("stdin") {
    Some(_) => true
    None => false
  }
  let path = match matches.value_by_positional("input") {
    Some(v) => v
    None => ""
  }
  { path, stdin }
}

///|
async fn main {
  let config = match try {
    @argparse.parse(
      @argparse.Command(
        "tomljson",
        about="Convert TOML to JSON",
        flags=[
          @argparse.FlagArg("stdin", long="stdin",
            about="Read TOML from stdin"),
        ],
        positionals=[
          @argparse.PositionArg("input", default_values=["-"],
            about="TOML file path"),
        ],
      ),
    )
  } catch {
    _ => {
      @stdio.stderr.write("Usage: tomljson [--stdin] [file]\n")
      return
    }
  }
  let cfg = config_from_matches(config)
  let text = if cfg.stdin || cfg.path == "-" || cfg.path == "" {
    @stdio.stdin.read_all().text()
  } else {
    @fs.read_file(cfg.path).text()
  }
  match try { parse(text) } catch {
    err => {
      @stdio.stderr.write("Error: " + err.to_string() + "\n")
      return
    }
  } {
    json => {
      @stdio.stdout.write(json.stringify() + "\n")
    }
  }
}
"}

